import java.util.concurrent.*;
import java.util.concurrent.atomic.LongAdder;

public final class CriticalityAwareExecutor {
    public enum Criticality { CRITICAL, BEST_EFFORT }

    private static final int QUEUE_CAP = 512;
    private static final int SOFT_CAP_BEST_EFFORT = 358; // 70%

    private final BlockingQueue<Runnable> queue = new ArrayBlockingQueue<>(QUEUE_CAP);
    private final LongAdder shedBestEffort = new LongAdder();
    private final LongAdder rejectedCritical = new LongAdder();

    private final ThreadPoolExecutor pool = new ThreadPoolExecutor(
        32, 32, 0L, TimeUnit.MILLISECONDS, queue,
        r -> new Thread(r, "ledger-worker"),
        (r, exec) -> {
            rejectedCritical.increment();
            throw new RejectedExecutionException("Ledger executor saturated; return 503 Retry-After");
        }
    );

    public <T> CompletableFuture<T> submit(Criticality crit, Callable<T> task) {
        CompletableFuture<T> future = new CompletableFuture<>();
        if (crit == Criticality.BEST_EFFORT && queue.size() >= SOFT_CAP_BEST_EFFORT) {
            shedBestEffort.increment();
            future.completeExceptionally(new RejectedExecutionException("Shed BEST_EFFORT at 70% depth"));
            return future;
        }
        try {
            pool.execute(() -> {
                try {
                    future.complete(task.call());
                } catch (Throwable t) {
                    future.completeExceptionally(t);
                }
            });
        } catch (RejectedExecutionException ex) {
            future.completeExceptionally(ex);
        }
        return future;
    }
}

